/**
 * @file telemetry_types.h
 * @brief Authoritative C/C++ Binary Contracts, Wire Layouts, and Converters (v2.0)
 * @details Conforms to:
 *          - ICD-VMWARE-SOC-TWIN-20261029 (Rev 2)
 *          - project-control/.agents/rules/c_cpp_coding_standard.md
 *          - SPEC-PROTO-20261015-153000 (MiniMCProto v2.0.3)
 * Task ID: TWIN-02
 * Author: ARCH
 */

#ifndef AISOC_TELEMETRY_TYPES_H
#define AISOC_TELEMETRY_TYPES_H

#ifdef __cplusplus
extern "C" {
#endif

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

/* ========================================================================= */
/* 1. Protocol Constants and Sentinel Definitions                            */
/* ========================================================================= */

#define MINIMC_SOF_1                         0x55U
#define MINIMC_SOF_2                         0xAAU

/* Logical Node Identifiers */
#define MINIMC_DEV_INVALID                   0x00U
#define MINIMC_DEV_AP                        0x01U
#define MINIMC_DEV_MC                        0x02U
#define MINIMC_DEV_SCM_TH                    0x03U
#define MINIMC_DEV_RESERVED_TH_EXT           0x04U
#define MINIMC_DEV_CHAMBER                   0x05U
#define MINIMC_DEV_BROADCAST                 0xFFU

/* Protocol Flags (Offset 0x04) */
#define MINIMC_FLAG_WANTS_ACK                (1U << 0)
#define MINIMC_FLAG_IS_RESPONSE              (1U << 1)
#define MINIMC_FLAG_VERSION_MASK             0x0CU
#define MINIMC_FLAG_VERSION_2                0x04U /* 0b01 in bits 2..3 */
#define MINIMC_FLAG_IS_PRIORITY              (1U << 4)

/* Canonical Request / Response Flags */
#define MINIMC_REQ_FLAGS_V2                  (MINIMC_FLAG_VERSION_2 | MINIMC_FLAG_WANTS_ACK)   /* 0x05 */
#define MINIMC_RESP_FLAGS_V2                 (MINIMC_FLAG_VERSION_2 | MINIMC_FLAG_IS_RESPONSE) /* 0x06 */

/* Route Control Flags (Offset 0x07) */
#define MINIMC_ROUTE_FORCE_PRIMARY           (1U << 0)
#define MINIMC_ROUTE_ALLOW_REROUTE           (1U << 1)
#define MINIMC_ROUTE_IS_ROUTED               (1U << 2)

/* Command Identifiers */
#define MINIMC_CMD_ACK                       0x00U
#define MINIMC_CMD_GET_VERSION               0x01U
#define MINIMC_CMD_VERSION_REPORT            0x02U
#define MINIMC_CMD_PING                      0x03U
#define MINIMC_CMD_PONG                      0x04U
#define MINIMC_CMD_NACK                      0x06U
#define MINIMC_CMD_LOG_MESSAGE               0x07U
#define MINIMC_CMD_SYSTEM_CONTROL            0x10U
#define MINIMC_CMD_EMERGENCY_STOP            0x12U
#define MINIMC_CMD_TEMP_QUERY                0x14U
#define MINIMC_CMD_TEMP_REPORT               0x14U
#define MINIMC_CMD_OTA_START                 0x20U
#define MINIMC_CMD_OTA_DATA                  0x21U
#define MINIMC_CMD_OTA_FINISH                0x22U
#define MINIMC_CMD_OTA_STATUS                0x23U
#define MINIMC_CMD_STREAM_CHUNK              0x31U
#define MINIMC_CMD_TELEMETRY_REPORT          0x40U
#define MINIMC_CMD_ALARM_EVENT               0x50U

/* Wire Hardware Sensor Status Codes */
#define MINIMC_WIRE_STATUS_OK                0x00U
#define MINIMC_WIRE_STATUS_OPEN              0x01U
#define MINIMC_WIRE_STATUS_SHORT             0x02U
#define MINIMC_WIRE_STATUS_TIMEOUT           0x03U
#define MINIMC_WIRE_STATUS_UNKNOWN           0xFFU

/* Wire Temperature Range and Sentinels (0.1 deg C / deci_c) */
#define MINIMC_TEMP_DECI_MIN                 ((int16_t)-400)   /* -40.0 deg C */
#define MINIMC_TEMP_DECI_MAX                 ((int16_t)5000)   /* +500.0 deg C */
#define MINIMC_TEMP_SENTINEL_FAULT           ((int16_t)0x7FFF) /* +32767: Sensor fault */
#define MINIMC_TEMP_SENTINEL_OFFLINE         ((int16_t)0x7FFE) /* +32766: Offline / Timeout */

/* Internal Normalized Temperature Sentinels (0.001 deg C / millicelsius) */
#define AISOC_TEMP_MILLIC_MIN                ((int32_t)-40000)
#define AISOC_TEMP_MILLIC_MAX                ((int32_t)500000)
#define AISOC_TEMP_MILLIC_FAULT              ((int32_t)0x7FFFFFFF)
#define AISOC_TEMP_MILLIC_OFFLINE            ((int32_t)0x7FFFFFFE)

/* Buffer and Packet Dimensions */
#define MINIMC_HEADER_SIZE                   12U
#define MINIMC_CRC16_SIZE                    2U
#define MINIMC_MIN_FRAME_SIZE                14U
#define MINIMC_MAX_PAYLOAD_LEN               1024U
#define MINIMC_MAX_FRAME_SIZE                1038U
#define MINIMC_TEMP_PAYLOAD_SIZE             16U

/* Timing and Freshness Thresholds */
#define AISOC_FRESHNESS_STALE_MS             3000U
#define AISOC_FRESHNESS_FAULT_MS             10000U
#define AISOC_VMWARE_TX_TIMEOUT_MS           200U
#define AISOC_SOC_TX_TIMEOUT_MS              50U

/* CRC-16/CCITT-FALSE Calculation Parameters */
#define MINIMC_CRC16_CCITT_INIT              0xFFFFU
#define MINIMC_CRC16_CCITT_POLYNOMIAL        0x1021U
#define MINIMC_CRC16_CCITT_MSB_MASK          0x8000U
#define MINIMC_BITS_PER_BYTE                 8U

/* Unified Status Return Codes */
typedef enum {
    TELEMETRY_OK                   =  0,
    TELEMETRY_ERR_NULL_PTR         = -1,
    TELEMETRY_ERR_INVALID_PARAM    = -2,
    TELEMETRY_ERR_RANGE_EXCEEDED   = -3,
    TELEMETRY_ERR_INVALID_HEADER   = -4,
    TELEMETRY_ERR_CRC_MISMATCH     = -5,
    TELEMETRY_ERR_BUFFER_TOO_SMALL = -6
} telemetry_status_t;

/* Sensor Status Enumeration */
typedef enum {
    AISOC_SENSOR_OK      = 0,
    AISOC_SENSOR_OPEN    = 1,
    AISOC_SENSOR_SHORT   = 2,
    AISOC_SENSOR_TIMEOUT = 3,
    AISOC_SENSOR_UNKNOWN = 4
} aisoc_sensor_status_t;

/* Data Quality Enumeration */
typedef enum {
    AISOC_QUALITY_UNKNOWN = 0,
    AISOC_QUALITY_FRESH   = 1,
    AISOC_QUALITY_STALE   = 2,
    AISOC_QUALITY_FAULT   = 3
} aisoc_data_quality_t;

/* ========================================================================= */
/* 2. Wire Structure Definitions (Packed, Natural Alignment)                 */
/* ========================================================================= */

#pragma pack(push, 1)

/**
 * @brief 12-byte hardware-aligned MiniMCProto v2.0 frame header
 */
typedef struct {
    uint8_t  sof_1;       /**< 0x55 magic */
    uint8_t  sof_2;       /**< 0xAA magic */
    uint8_t  src_id;      /**< Source device ID */
    uint8_t  dst_id;      /**< Destination device ID */
    uint8_t  flags;       /**< Control flags (v2 version in bits 2..3) */
    uint8_t  cmd_id;      /**< Command identifier */
    uint8_t  hop_limit;   /**< Hop limit (TTL) */
    uint8_t  route_ctrl;  /**< Routing control flags */
    uint16_t seq;         /**< 16-bit sequence number (little-endian) */
    uint16_t payload_len; /**< 16-bit payload length (little-endian) */
} minimc_header_t;

/**
 * @brief 16-byte packed temperature report wire payload (v2.0)
 * @details Transmitted over UART with 0.1 deg C resolution (deci_c).
 */
typedef struct {
    int16_t  current_temp_deci_c; /**< Measured temperature (0.1 deg C, -400..5000, 0x7FFF/0x7FFE sentinels) */
    int16_t  target_temp_deci_c;  /**< Target temperature (0.1 deg C, fixed 0 for read-only slice) */
    uint16_t raw_adc_value;       /**< Raw 12-bit ADC conversion (0..4095) */
    uint8_t  sensor_status;       /**< Hardware sensor status (0x00 OK, 0x01 OPEN, 0x02 SHORT, 0x03 TIMEOUT) */
    uint8_t  heater_duty_percent; /**< PWM duty cycle percentage (locked 0 for read-only slice) */
    uint32_t sample_timestamp_ms; /**< Monotonic MCU sample timestamp in ms */
    uint32_t reserved;            /**< Alignment padding, must be 0 */
} minimc_temp_wire_payload_t;

#pragma pack(pop)

/* Compile-time Layout and Size Assertions */
#if defined(__cplusplus)
static_assert(sizeof(minimc_header_t) == MINIMC_HEADER_SIZE,
              "minimc_header_t size must be exactly 12 bytes");
static_assert(sizeof(minimc_temp_wire_payload_t) == MINIMC_TEMP_PAYLOAD_SIZE,
              "minimc_temp_wire_payload_t size must be exactly 16 bytes");
#elif defined(__STDC_VERSION__) && (__STDC_VERSION__ >= 201112L)
_Static_assert(sizeof(minimc_header_t) == MINIMC_HEADER_SIZE,
               "minimc_header_t size must be exactly 12 bytes");
_Static_assert(sizeof(minimc_temp_wire_payload_t) == MINIMC_TEMP_PAYLOAD_SIZE,
               "minimc_temp_wire_payload_t size must be exactly 16 bytes");
#endif

/* ========================================================================= */
/* 3. Static Inline Helper Functions (Strict Gatekeeper Compliant)           */
/* ========================================================================= */

/**
 * @brief Check if a wire temperature value represents a fault or offline sentinel.
 * @param deci_c Wire temperature in 0.1 deg C
 * @return true if sentinel, false if valid measurement
 */
static inline bool telemetry_is_wire_sentinel(int16_t deci_c) {
    const bool is_fault = (deci_c == MINIMC_TEMP_SENTINEL_FAULT);
    const bool is_offline = (deci_c == MINIMC_TEMP_SENTINEL_OFFLINE);
    return is_fault || is_offline;
}

/**
 * @brief Convert wire deci_c (0.1 deg C) to normalized internal millicelsius (0.001 deg C).
 * @param deci_c Input wire temperature
 * @param out_millic Output normalized temperature in millicelsius
 * @return Status code
 */
static inline telemetry_status_t telemetry_deci_to_millic(
    int16_t deci_c,
    int32_t *out_millic
) {
    if (out_millic == NULL) {
        return TELEMETRY_ERR_NULL_PTR;
    }

    if (deci_c == MINIMC_TEMP_SENTINEL_FAULT) {
        *out_millic = AISOC_TEMP_MILLIC_FAULT;
        return TELEMETRY_OK;
    }

    if (deci_c == MINIMC_TEMP_SENTINEL_OFFLINE) {
        *out_millic = AISOC_TEMP_MILLIC_OFFLINE;
        return TELEMETRY_OK;
    }

    const bool below_min = (deci_c < MINIMC_TEMP_DECI_MIN);
    const bool above_max = (deci_c > MINIMC_TEMP_DECI_MAX);
    if (below_min || above_max) {
        return TELEMETRY_ERR_RANGE_EXCEEDED;
    }

    const int32_t val = (int32_t)deci_c;
    *out_millic = val * 100;
    return TELEMETRY_OK;
}

/**
 * @brief Convert internal millicelsius (0.001 deg C) to wire deci_c (0.1 deg C).
 * @param millic Input internal temperature in millicelsius
 * @param out_deci_c Output wire temperature
 * @return Status code
 */
static inline telemetry_status_t telemetry_millic_to_deci(
    int32_t millic,
    int16_t *out_deci_c
) {
    if (out_deci_c == NULL) {
        return TELEMETRY_ERR_NULL_PTR;
    }

    if (millic == AISOC_TEMP_MILLIC_FAULT) {
        *out_deci_c = MINIMC_TEMP_SENTINEL_FAULT;
        return TELEMETRY_OK;
    }

    if (millic == AISOC_TEMP_MILLIC_OFFLINE) {
        *out_deci_c = MINIMC_TEMP_SENTINEL_OFFLINE;
        return TELEMETRY_OK;
    }

    const bool below_min = (millic < AISOC_TEMP_MILLIC_MIN);
    const bool above_max = (millic > AISOC_TEMP_MILLIC_MAX);
    if (below_min || above_max) {
        return TELEMETRY_ERR_RANGE_EXCEEDED;
    }

    const int32_t scaled = millic / 100;
    *out_deci_c = (int16_t)scaled;
    return TELEMETRY_OK;
}

/**
 * @brief Map wire status code to canonical sensor status enum.
 * @param wire_status 8-bit wire status code
 * @param out_status Output sensor status enum
 * @return Status code
 */
static inline telemetry_status_t telemetry_map_sensor_status(
    uint8_t wire_status,
    aisoc_sensor_status_t *out_status
) {
    if (out_status == NULL) {
        return TELEMETRY_ERR_NULL_PTR;
    }

    switch (wire_status) {
        case MINIMC_WIRE_STATUS_OK:
            *out_status = AISOC_SENSOR_OK;
            break;
        case MINIMC_WIRE_STATUS_OPEN:
            *out_status = AISOC_SENSOR_OPEN;
            break;
        case MINIMC_WIRE_STATUS_SHORT:
            *out_status = AISOC_SENSOR_SHORT;
            break;
        case MINIMC_WIRE_STATUS_TIMEOUT:
            *out_status = AISOC_SENSOR_TIMEOUT;
            break;
        default:
            *out_status = AISOC_SENSOR_UNKNOWN;
            break;
    }
    return TELEMETRY_OK;
}

/**
 * @brief Evaluate data freshness quality based on elapsed monotonic milliseconds.
 * @param elapsed_ms Elapsed time since last received sample
 * @param sensor_status Physical status of the sensor
 * @param out_quality Output quality rating
 * @return Status code
 */
static inline telemetry_status_t telemetry_eval_data_quality(
    uint32_t elapsed_ms,
    aisoc_sensor_status_t sensor_status,
    aisoc_data_quality_t *out_quality
) {
    if (out_quality == NULL) {
        return TELEMETRY_ERR_NULL_PTR;
    }

    if (sensor_status != AISOC_SENSOR_OK) {
        *out_quality = AISOC_QUALITY_FAULT;
        return TELEMETRY_OK;
    }

    if (elapsed_ms < AISOC_FRESHNESS_STALE_MS) {
        *out_quality = AISOC_QUALITY_FRESH;
    } else if (elapsed_ms < AISOC_FRESHNESS_FAULT_MS) {
        *out_quality = AISOC_QUALITY_STALE;
    } else {
        *out_quality = AISOC_QUALITY_FAULT;
    }
    return TELEMETRY_OK;
}

/**
 * @brief Validate 12-byte frame header against MiniMCProto v2.0 invariants.
 * @param header Pointer to header struct
 * @param out_valid Output boolean indicating validity
 * @return Status code
 */
static inline telemetry_status_t telemetry_validate_header(
    const minimc_header_t *header,
    bool *out_valid
) {
    if (header == NULL || out_valid == NULL) {
        return TELEMETRY_ERR_NULL_PTR;
    }

    *out_valid = false;
    const bool magic_valid = (header->sof_1 == MINIMC_SOF_1) && (header->sof_2 == MINIMC_SOF_2);
    const bool ver_valid = ((header->flags & MINIMC_FLAG_VERSION_MASK) == MINIMC_FLAG_VERSION_2);
    const bool len_valid = (header->payload_len <= MINIMC_MAX_PAYLOAD_LEN);

    if (magic_valid && ver_valid && len_valid) {
        *out_valid = true;
    }
    return TELEMETRY_OK;
}

/**
 * @brief Compute CRC-16/CCITT-FALSE over buffer (step-by-step, no compressed arithmetic).
 * @param data Input byte buffer
 * @param len Byte count
 * @param out_crc Output calculated 16-bit CRC
 * @return Status code
 */
static inline telemetry_status_t telemetry_calc_crc16(
    const uint8_t *data,
    size_t len,
    uint16_t *out_crc
) {
    if (data == NULL || out_crc == NULL) {
        return TELEMETRY_ERR_NULL_PTR;
    }

    uint16_t crc = MINIMC_CRC16_CCITT_INIT;
    for (size_t i = 0; i < len; ++i) {
        const uint8_t byte_val = data[i];
        crc ^= (uint16_t)((uint16_t)byte_val << MINIMC_BITS_PER_BYTE);
        for (uint8_t bit = 0; bit < MINIMC_BITS_PER_BYTE; ++bit) {
            const bool msb_set = ((crc & MINIMC_CRC16_CCITT_MSB_MASK) != 0U);
            if (msb_set) {
                crc = (uint16_t)((crc << 1U) ^ MINIMC_CRC16_CCITT_POLYNOMIAL);
            } else {
                crc = (uint16_t)(crc << 1U);
            }
        }
    }

    *out_crc = crc;
    return TELEMETRY_OK;
}

